    if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.detail||(hi?'आवाज़ तैयार नहीं हो सकी। फिर कोशिश करें।':'Natural voice could not be prepared. Please try again.'))}
    audioBlob=await response.blob();if(!audioBlob.size)throw new Error(hi?'खाली ऑडियो मिला। फिर कोशिश करें।':'The voice service returned empty audio. Please try again.');
    speechCacheRef.current.set(cacheKey,audioBlob);if(speechCacheRef.current.size>6)speechCacheRef.current.delete(speechCacheRef.current.keys().next().value);
