 const saveFarm=()=>{const farm={locationId,districtId,locationName,cropName:cropName||'',savedAt:new Date().toISOString()},next=[farm,...farms.filter(x=>x.locationId!==locationId)];setFarms(next);localStorage.setItem(farmKey,JSON.stringify(next));setSaved(true);setTimeout(()=>setSaved(false),2200)};
