 const checkReminders=()=>{if(reminderPermission!=='granted')return;const today=new Date().toISOString().slice(0,10);for(const r of records.filter(x=>x.record_type==='reminder'&&x.recorded_on<=today)){const k=`mausam-reminder-${profile?.id||profile?.location_id}-${r.id||r.client_id||r.local_id}`;if(!localStorage.getItem(k)){new Notification(hi?'Mausam · खेत का रिमाइंडर':'Mausam · farm reminder',{body:r.title});localStorage.setItem(k,'1')}}};
 React.useEffect(()=>{if(reminderPermission!=='granted')return;checkReminders();const timer=setInterval(checkReminders,60*60*1000);window.addEventListener('focus',checkReminders);return()=>{clearInterval(timer);window.removeEventListener('focus',checkReminders)}},[records,reminderPermission]);
 const persistLocal=next=>{setRecords(next);localStorage.setItem(key,JSON.stringify(next));setStorage('device')};
 const submitRecord=async e=>{e.preventDefault();if(!title.trim())return;const item={record_type:kind,recorded_on:recordDate,title:title.trim(),details:details.trim(),quantity:null,unit:null,amount:kind==='expense'&&cost?Number(cost):null,metadata:{crop:profile?.crop_name||''},client_id:globalThis.crypto?.randomUUID?globalThis.crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)}),local_id:''};try{item.local_id=item.client_id;const result=await api('/farm-records/me',{method:'POST',body:JSON.stringify({...item,local_id:undefined})});const next=[result.record,...records];setRecords(next);localStorage.setItem(key,JSON.stringify(next));setStorage('database');setStatus(hi?'नोट खेत की डायरी में सहेजा गया।':'Saved to your farm diary.')}catch{persistLocal([item,...records]);setStatus(hi?'डेटाबेस उपलब्ध नहीं था; यह नोट इसी डिवाइस पर सहेजा गया।':'Database unavailable; this note is saved on this device only.')}setTitle('');setDetails('');setCost('')};
