 const coords=[];const walk=c=>{if(!Array.isArray(c))return;if(typeof c[0]==='number'){coords.push(c);return}c.forEach(walk)};features.forEach(f=>walk(f.geometry?.coordinates));districtFeatures.forEach(f=>walk(f.geometry?.coordinates));
 const xs=coords.map(p=>p[0]),ys=coords.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),dx=maxX-minX||1,dy=maxY-minY||1;
 const project=([x,y])=>[30+(x-minX)/dx*740,25+(maxY-y)/dy*440];
