 const palette=mode==='rain'?['#e7e4d8','#c8ddce','#79bd9e','#32a3a0','#3478a4','#704d9b']:mode==='temp'?['#344f94','#508ab8','#75b895','#e5ca67','#eb9451','#bd4651']:mode==='wind'?['#e7e4d8','#c8ddce','#79bd9e','#32a3a0','#3478a4','#704d9b']:mode==='alerts'?['#a9aa9f','#8bad78','#e5a04d','#bd4651']:['#e7e4d8','#c8ddce','#79bd9e','#32a3a0','#3478a4','#704d9b'];
 const colorFor=v=>{if(v==null)return '#a9aa9f';if(mode==='rain')return rainfallColor(v);if(mode==='temp')return v<20?'#344f94':v<25?'#508ab8':v<30?'#75b895':v<35?'#e5ca67':v<40?'#eb9451':'#bd4651';if(mode==='wind')return v<10?'#e7e4d8':v<20?'#c8ddce':v<30?'#79bd9e':v<40?'#32a3a0':v<60?'#3478a4':'#704d9b';return v<20?'#e7e4d8':v<40?'#c8ddce':v<60?'#79bd9e':v<80?'#32a3a0':v<95?'#3478a4':'#704d9b'};
 const condition=(rec)=>{if(!rec)return hi?'मौसम उपलब्ध नहीं':'Weather unavailable';const slots=Math.max(1,Math.round(6/(Number(rec.forecast.resolution_hours)||1)));const code=step===0?rec.forecast.current?.weather_code:rec.forecast.hourly?.weather_code?.[Math.min((rec.forecast.hourly?.weather_code||[]).length-1,forecastIndex(rec)+step*slots-1)];return weatherCondition(code,lang)};
 const averageDaily=(days)=>{const records=weather?.records||[];if(!records.length)return null;const totals=records.map(r=>dailyWindow(r,days).rain);return totals.every(Number.isFinite)?totals.reduce((a,b)=>a+b,0)/totals.length:null};
